tml": "<p><span style=\"color: rgb(0, 0, 0); font-family: -webkit-standard;\">Birthstone necklaces and pendants in gold vermeil, guided by Vedic astrology and the Western zodiac. One natural gemstone for every month, sign and story.</span></p>"}, {"id": "f066e50d-f9a3-4b04-87ba-f78dfbcde1eb", "slug": "earrings", "name": "Earrings", "description": "Statement Earrings | Lab-Grown Gemstone Jewelry in 925 Silver", "hero_image": "https://qsjzdfwvxshuazhgqoll.supabase.co/storage/v1/object/sign/admin-media/2026/7dfd781d-46e3-4a1f-9ef5-0a0c9eeab6bb-IMG_8156.jpg?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV85ZDgyYzI2Zi0zY2Y2LTQ1MTQtOWJlYy1hZjQ1MTlmNmE1ZmUiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJhZG1pbi1tZWRpYS8yMDI2LzdkZmQ3ODFkLTQ2ZTMtNGExZi05ZWY1LTBhMGM5ZWVhYjZiYi1JTUdfODE1Ni5qcGciLCJzY29wZSI6ImRvd25sb2FkIiwiaWF0IjoxNzg2MDAzNTU3LCJleHAiOjI0MTY3MjM1NTd9.EinJsCzTOUBkkdc2v6MH4QwUhw1BuygbgJvI_rDpeiY", "sort_order": 7, "created_at": "2026-07-08T16:18:32.32986+00:00", "meta_title": "Statement Earrings | Lab-Grown Gemstone Jewelry in 925 Silver", "meta_description": "Bold lab-grown gemstone earrings in 925 silver with rhodium finish \u2014 moissanite, convertible drops and party-wear statement pieces designed to sparkle.", "updated_at": "2026-09-02T08:23:52.496308+00:00", "description_html": "<p>Bold lab-grown gemstone earrings in 925 silver with rhodium finish \u2014 moissanite, convertible drops and party-wear statement pieces designed to sparkle.</p>"}, {"id": "07f979a5-a378-496c-9ddb-d7e29911bd41", "slug": "ether", "name": "Ether Energy Crystals", "description": "For the days you need stillness. Ether pieces carry the energy of protection, presence, and quiet connection.", "hero_image": "https://qsjzdfwvxshuazhgqoll.supabase.co/storage/v1/object/sign/admin-media/2026/3391ee71-9ab6-4093-a889-6096cce8d9fa-ChatGPT_Image_Sep_2__2026_at_01_22_38_PM.png?token=eyJraWQiOiI5ZDgyYzI2Zi0zY2Y2LTQ1MTQtOWJlYy1hZjQ1MTlmNmE1ZmUiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJhZG1pbi1tZWRpYS8yMDI2LzMzOTFlZTcxLTlhYjYtNDA5My1hODg5LTYwOTZjY2U4ZDlmYS1DaGF0R1BUX0ltYWdlX1NlcF8yX18yMDI2X2F0XzAxXzIyXzM4X1BNLnBuZyIsInNjb3BlIjoiZG93bmxvYWQiLCJpYXQiOjE3ODgzMzU3NzAsImV4cCI6MjQxOTA1NTc3MH0.gprVozvu9OwgiXBeq9xMtDa1IkVCLdj6ICiyqYTJmaI", "sort_order": 14, "created_at": "2026-08-18T11:37:30.515502+00:00", "meta_title": "Ether Element Gemstone Jewelry | Stillness & Presence \u2013 Rosado Gems", "meta_description": "Explore the Ether collection \u2014 natural gemstone jewelry carrying the energy of stillness, protection and quiet presence.", "updated_at": "2026-09-02T08:26:14.465493+00:00", "description_html": "<p>Ether is the element beyond the four \u2014 the quiet space that holds Fire, Earth, Water, and Air together. Where the others move and shift, Ether simply is: still, protective, unifying.</p><p>The Ether collection is for the moments you''re seeking not to <em>do</em> more, but to <em>be</em> more present \u2014 during meditation, prayer, or simply a quiet morning before the day begins. It is the space where all the other elements come to rest.</p><p>Every piece is a natural gemstone, sourced with the same honesty behind every Rosado Gems piece.</p>"}, {"id": "00e60e51-ae64-47cf-8468-83008fa5e3de", "slug": "energy-crystal-jaap-malas", "name": "Crystal Energy Jaap Malas 108 Beads", "description": "Natural gemstone beads bracelets. Wear an energy everyday with intention for enhancing the effect of natural gemstones to bring positivity and emotional well-being. 108 Bead Jaap Malas | Crystal Energy Malas for Meditation", "hero_image": "https://qsjzdfwvxshuazhgqoll.supabase.co/storage/v1/object/sign/admin-media/2026/a2ea9d7f-88ea-4d79-a692-b00bf9fb4224-ChatGPT_Image_Aug_11__2026_at_01_49_19_PM.png?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV85ZDgyYzI2Zi0zY2Y2LTQ1MTQtOWJlYy1hZjQ1MTlmNmE1ZmUiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJhZG1pbi1tZWRpYS8yMDI2L2EyZWE5ZDdmLTg4ZWEtNGQ3OS1hNjkyLWIwMGJmOWZiNDIyNC1DaGF0R1BUX0ltYWdlX0F1Z18xMV9fMjAyNl9hdF8wMV80OV8xOV9QTS5wbmciLCJzY29wZSI6ImRvd25sb2FkIiwiaWF0IjoxNzg2NDY2ODQwLCJleHAiOjI0MTcxODY4NDB9.fsypHYbFtwZJZUajs9gOte6N7U7ficgoYEfxqh6syxI", "sort_order": 9, "created_at": "2026-07-08T16:18:32.32986+00:00", "meta_title": "108 Bead Jaap Malas | Crystal Energy Malas for Meditation", "meta_description": "Hand-strung 108-bead jaap malas in natural gemstones with a lava rock guru bead for essential oils. Cotton tassel, silk pouch. Part of the Gem Poetry edit.", "updated_at": "2026-09-02T08:24:32.720747+00:00", "description_html": "<p>Natural gemstone malas with 108 beads that promote energy healing to bring well-being and positivity. Useful in meditation and chanting. <span style=\"color: rgb(0, 0, 0); font-family: -webkit-standard;\">Hand-strung 108-bead jaap malas in natural gemstones with a lava rock guru bead for essential oils. Cotton tassel, silk pouch. Part of the Gem Poetry edit.</span></p>"}, {"id": "329b1cbc-d6d2-40bc-a1ef-4fb42b6cc011", "slug": "gem-poetry", "name": "Gem Poetry \u2014 Every Gem Tells a Story", "description": "The Gem Edit is a new curated product category featuring a hand-selected collection gemstone jewellery. Discover your stone because what you are seeking is seeking you!", "hero_image": "https://qsjzdfwvxshuazhgqoll.supabase.co/storage/v1/object/sign/admin-media/2026/682d8382-c861-45af-a535-acb6a770ebaf-Photoroom_20260728_150114.JPG?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV85ZDgyYzI2Zi0zY2Y2LTQ1MTQtOWJlYy1hZjQ1MTlmNmE1ZmUiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJhZG1pbi1tZWRpYS8yMDI2LzY4MmQ4MzgyLWM4NjEtNDVhZi1hNTM1LWFjYjZhNzcwZWJhZi1QaG90b3Jvb21fMjAyNjA3MjhfMTUwMTE0LkpQRyIsInNjb3BlIjoiZG93bmxvYWQiLCJpYXQiOjE3ODYwMDM2MDUsImV4cCI6MjQxNjcyMzYwNX0.Hd8UOSwQ_DA0CATQBxr1EacHCn2bNbktXhthHbF9jYQ", "sort_order": 1, "created_at": "2026-07-08T16:18:32.32986+00:00", "meta_title": "Gem Poetry | Natural Gemstone Jewelry \u2014 Rings, Necklaces & Malas", "meta_description": "Natural gemstone rings, necklaces, pendants and 108-bead jaap malas in 925 silver \u2014 organized by element energy and birthstone. Certified, GIA-informed.", "updated_at": "2026-08-10T12:07:39.376471+00:00", "description_html": "<p>Gemstone jewellery in 925 silver sourced ethically and produced with intention. Every piece is energised by a certified energy healer and sent to you with intention. Discover what kind of energy calls out to you and wear it in good health. All pieces are certified and you shall receive a third party Laboratory certificate.</p>"}, {"id": "d46d1274-eea6-437f-9d5a-28db512eca43", "slug": "earth", "name": "Earth Energy Crystals", "description": "For the days you need to feel steady. Earth pieces carry the energy of stability, patience, and quiet strength.", "hero_image": "https://qsjzdfwvxshuazhgqoll.supabase.co/storage/v1/object/sign/admin-media/2026/ce63a7b4-ab79-46c9-9a3e-9875b4eaa872-ChatGPT_Image_Sep_2__2026_at_01_12_15_PM.png?token=eyJraWQiOiI5ZDgyYzI2Zi0zY2Y2LTQ1MTQtOWJlYy1hZjQ1MTlmNmE1ZmUiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJhZG1pbi1tZWRpYS8yMDI2L2NlNjNhN2I0LWFiNzktNDZjOS05YTNlLTk4NzViNGVhYTg3Mi1DaGF0R1BUX0ltYWdlX1NlcF8yX18yMDI2X2F0XzAxXzEyXzE1X1BNLnBuZyIsInNjb3BlIjoiZG93bmxvYWQiLCJpYXQiOjE3ODgzMzU3MjYsImV4cCI6MjQxOTA1NTcyNn0.NKrYE9klUcGWy5f7PR3oOVC6wRuwgo3dPxi5ixThD4I", "sort_order": 11, "created_at": "2026-08-18T11:31:06.023178+00:00", "meta_title": "Earth Element Gemstone Jewelry | Stability & Strength \u2013 Rosado Gems", "meta_description": "Discover the Earth collection \u2014 natural gemstone jewelry carrying the energy of stability, patience and grounding strength. Ethically sourced.", "updated_at": "2026-09-02T08:25:29.04963+00:00", "description_html": "<p>Earth is the element of roots \u2014 patient, steady, unshaken by noise. Where other energies move fast, Earth holds still and holds true.</p><p>The Earth collection is for anyone who needs to feel anchored \u2014 through a hard decision, a long project, or a season of change. It doesn''t shout. It simply stays, the way the ground beneath you stays, so you can move forward from solid footing.</p><p>Every piece is a natural gemstone, chosen the way we choose everything at Rosado Gems \u2014 with honesty about origin and character.</p>"}, {"id": "21581a2b-e671-49a6-b47f-f8f398d42291", "slug": "diy", "name": "Make Your Own Earrings", "description": "Several accessories to choose from to make your own convertible earrings", "hero_image": "https://qsjzdfwvxshuazhgqoll.supabase.co/storage/v1/object/sign/admin-media/2026/51a0ef51-4012-47c0-963b-48c55696fd0e-IMG_8238-Photoroom.JPG?token=eyJraWQiOiI5ZDgyYzI2Zi0zY2Y2LTQ1MTQtOWJlYy1hZjQ1MTlmNmE1ZmUiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJhZG1pbi1tZWRpYS8yMDI2LzUxYTBlZjUxLTQwMTItNDdjMC05NjNiLTQ4YzU1Njk2ZmQwZS1JTUdfODIzOC1QaG90b3Jvb20uSlBHIiwic2NvcGUiOiJkb3dubG9hZCIsImlhdCI6MTc4ODMzMzM4MSwiZXhwIjoyNDE5MDUzMzgxfQ.TlrcXsfOSIwp0nhyQdy7oThZnn6tzanuJKNbYCq1gVc", "sort_order": 3, "created_at": "2026-09-02T07:16:01.973149+00:00", "meta_title": "", "meta_description": "", "updated_at": "2026-09-02T08:22:33.261064+00:00", "description_html": ""}, {"id": "d66af0d6-8fe4-49dd-821c-915d8f17e803", "slug": "navratna", "name": "Navratna", "description": "9 gemstones, 9 planets, 9 energies", "hero_image": "https://qsjzdfwvxshuazhgqoll.supabase.co/storage/v1/object/sign/admin-media/2026/a0e580c5-e71e-4589-83c8-bea56bded094-ChatGPT_Image_Aug_11__2026_at_03_37_19_PM.png?token=eyJraWQiOiI5ZDgyYzI2Zi0zY2Y2LTQ1MTQtOWJlYy1hZjQ1MTlmNmE1ZmUiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJhZG1pbi1tZWRpYS8yMDI2L2EwZTU4MGM1LWU3MWUtNDU4OS04M2M4LWJlYTU2YmRlZDA5NC1DaGF0R1BUX0ltYWdlX0F1Z18xMV9fMjAyNl9hdF8wM18zN18xOV9QTS5wbmciLCJzY29wZSI6ImRvd25sb2FkIiwiaWF0IjoxNzg4MzMyODQ3LCJleHAiOjI0MTkwNTI4NDd9.pIAFv-5_lqCtBOJ73qFdfUKMjpDHAdLQeMdza4A65yY", "sort_order": 4, "created_at": "2026-09-02T07:07:33.375403+00:00", "meta_title": "", "meta_description": "", "updated_at": "2026-09-02T08:22:41.903851+00:00", "description_html": ""}, {"id": "7d4b7a09-00eb-4ab2-93c2-d31d6bdbc9d5", "slug": "classics", "name": "Classics", "description": "Everyday sparkle for daily wear", "hero_image": "https://qsjzdfwvxshuazhgqoll.supabase.co/storage/v1/object/sign/admin-media/2026/6d1709fa-718b-4b92-8914-2eaa96c980db-ChatGPT_Image_Aug_1__2026_at_04_47_15_PM.png?token=eyJraWQiOiI5ZDgyYzI2Zi0zY2Y2LTQ1MTQtOWJlYy1hZjQ1MTlmNmE1ZmUiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJhZG1pbi1tZWRpYS8yMDI2LzZkMTcwOWZhLTcxOGItNGI5Mi04OTE0LTJlYWE5NmM5ODBkYi1DaGF0R1BUX0ltYWdlX0F1Z18xX18yMDI2X2F0XzA0XzQ3XzE1X1BNLnBuZyIsInNjb3BlIjoiZG93bmxvYWQiLCJpYXQiOjE3ODgzMzI3OTEsImV4cCI6MjQxOTA1Mjc5MX0.6sBj3vOy-Xc7ksxhXT2aPnXLRwrzbHFEZRlnpJt-kcg", "sort_order": 5, "created_at": "2026-09-02T07:06:37.023072+00:00", "meta_title": "", "meta_description": "", "updated_at": "2026-09-02T08:22:51.086817+00:00", "description_html": ""}, {"id": "9e7cb935-075e-4bdc-9704-ff9a2f4c4d70", "slug": "fire", "name": "Fire Energy Crystals", "description": "For the days you need to move, decide, and show up boldly. Fire pieces carry the energy of confidence, passion, and momentum.", "hero_image": "https://qsjzdfwvxshuazhgqoll.supabase.co/storage/v1/object/sign/admin-media/2026/4b63b193-8943-4136-89cf-aa8fb3b5a78f-ChatGPT_Image_Sep_2__2026_at_01_15_57_PM.png?token=eyJraWQiOiI5ZDgyYzI2Zi0zY2Y2LTQ1MTQtOWJlYy1hZjQ1MTlmNmE1ZmUiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJhZG1pbi1tZWRpYS8yMDI2LzRiNjNiMTkzLTg5NDMtNDEzNi04OWNmLWFhOGZiM2I1YTc4Zi1DaGF0R1BUX0ltYWdlX1NlcF8yX18yMDI2X2F0XzAxXzE1XzU3X1BNLnBuZyIsInNjb3BlIjoiZG93bmxvYWQiLCJpYXQiOjE3ODgzMzU3MTEsImV4cCI6MjQxOTA1NTcxMX0.i07qgZEH7A_bKIn27T6Dpfu14VC2JEdui1YOcs4Bs1c", "sort_order": 10, "created_at": "2026-08-18T11:30:15.389209+00:00", "meta_title": "Fire Element Gemstone Jewelry | Confidence & Courage \u2013 Rosado Gems", "meta_description": "Shop the Fire collection \u2014 natural gemstone jewelry carrying the energy of confidence, passion and momentum. GIA-sourced, ethically crafted.", "updated_at": "2026-09-02T08:25:18.588588+00:00", "description_html": "<p>Fire is the element of ignition \u2014 the spark that turns intention into action. It''s the energy of courage, of starting before you feel ready, of choosing yourself without apology.</p><p>Our Fire collection is for anyone who wants a little more heat in their day. These are pieces to reach for before a big decision, a difficult conversation, or simply a day you want to walk into with your shoulders back. This is not jewelry that waits quietly in a drawer \u2014 it''s an everyday companion for the days you choose to burn bright.</p><p>Every piece in this collection is a natural gemstone, sourced with the same transparency behind every Rosado Gems verse \u2014 honestly described, ethically chosen.</p>"}, {"id": "2590e73f-0e3d-4bb1-acd1-6a5e374525c0", "slug": "water", "name": "Water Energy Crystals", "description": "For the days that ask more of your heart than your head. Water pieces carry the energy of intuition, calm, and emotional depth.", "hero_image": "https://qsjzdfwvxshuazhgqoll.supabase.co/storage/v1/object/sign/admin-media/2026/49d403ea-c366-4df9-b593-a2863e7b2438-ChatGPT_Image_Sep_2__2026_at_01_14_46_PM.png?token=eyJraWQiOiI5ZDgyYzI2Zi0zY2Y2LTQ1MTQtOWJlYy1hZjQ1MTlmNmE1ZmUiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJhZG1pbi1tZWRpYS8yMDI2LzQ5ZDQwM2VhLWMzNjYtNGRmOS1iNTkzLWEyODYzZTdiMjQzOC1DaGF0R1BUX0ltYWdlX1NlcF8yX18yMDI2X2F0XzAxXzE0XzQ2X1BNLnBuZyIsInNjb3BlIjoiZG93bmxvYWQiLCJpYXQiOjE3ODgzMzU3MzksImV4cCI6MjQxOTA1NTczOX0.sWADiBRlPwkEywKoxlcbsf1C7jAi4IRe450riyALG6Q", "sort_order": 12, "created_at": "2026-08-18T11:35:52.893569+00:00", "meta_title": "Water Element Gemstone Jewelry | Calm & Intuition \u2013 Rosado Gems", "meta_description": "Shop the Water collection \u2014 natural gemstone jewelry carrying the energy of intuition, calm and emotional balance. Ethically sourced.", "updated_at": "2026-09-02T08:25:50.507784+00:00", "description_html": "<p>Water is the element of feeling \u2014 it moves where logic can''t reach, carrying intuition, memory, and quiet emotional depth.</p><p>The Water collection is for anyone whose inner world runs deep \u2014 for a hard conversation, a return to yourself, or a moment of rest you''ve been putting off. Let it be the quiet reminder that softness is its own kind of strength.</p><p>Every piece is a natural gemstone, chosen and described with the transparency our founder''s years in the Jaipur gem markets and GIA training taught her to value.</p>"}, {"id": "8910aeea-1a91-4d8c-81ec-f748793f6f24", "slug": "air", "name": "Air Energy Crystals", "description": "For the days you need clarity. Air pieces carry the energy of focus, expression, and open communication.", "hero_image": "https://qsjzdfwvxshuazhgqoll.supabase.co/storage/v1/object/sign/admin-media/2026/563c98be-4c42-4feb-909a-524a20a94dae-ChatGPT_Image_Sep_2__2026_at_01_20_01_PM.png?token=eyJraWQiOiI5ZDgyYzI2Zi0zY2Y2LTQ1MTQtOWJlYy1hZjQ1MTlmNmE1ZmUiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJhZG1pbi1tZWRpYS8yMDI2LzU2M2M5OGJlLTRjNDItNGZlYi05MDlhLTUyNGEyMGE5NGRhZS1DaGF0R1BUX0ltYWdlX1NlcF8yX18yMDI2X2F0XzAxXzIwXzAxX1BNLnBuZyIsInNjb3BlIjoiZG93bmxvYWQiLCJpYXQiOjE3ODgzMzU3NTUsImV4cCI6MjQxOTA1NTc1NX0.IAiXkyZY0vOqDU-T6cLC2DYDjq-Uou8o3EW-58YgkOw", "sort_order": 13, "created_at": "2026-08-18T11:36:38.758791+00:00", "meta_title": "Air Element Gemstone Jewelry | Clarity & Expression \u2013 Rosado Gems", "meta_description": "Discover the Air collection \u2014 natural gemstone jewelry carrying the energy of clarity, focus and open expression. Ethically sourced.", "updated_at": "2026-09-02T08:25:58.528649+00:00", "description_html": "<p>Air is the element of thought \u2014 quick, clear, always reaching for connection. It''s the breath behind every idea, every conversation, every new perspective.</p><p>The Air collection is for anyone whose mind moves fast \u2014 a presentation, a hard conversation, a room full of new people. It''s a small, constant reminder to think clearly and speak honestly, even when the moment feels loud.</p><p>Every piece is a natural gemstone, sourced and described with the same transparency-first philosophy behind every Rosado Gems collection.</p>"}]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.products SELECT * FROM jsonb_populate_recordset(NULL::public.products, '[{"id": "fb3b3cb0-b5f1-4eb9-a558-94fa2baaec32", "slug": "Tidal Verse \u2014 Aquamarine Necklace", "category_id": "c6fb8e9c-678f-47d5-a9ca-f3b1ee9b99e0", "name": "Tidal Verse \u2014 Aquamarine Necklace", "description": "<p><span style=\"color: rgb(0, 0, 0); font-family: Arial;\">Aquamarine Necklace, natural stone in 925 sterling silver, made to be worn every day. Aquamarine is a Water gemstone \u2014 she carries the energy of intuition, calm and clear emotional flow, like a low tide that never quite goes out. She is also March''s birthstone and the gemstone of Pisces (Feb 19 \u2013 Mar 20), a sign that dreams in feeling, though her calm belongs to anyone who wants to move through the day a little more gently. 5mm, precision-cut stones, light enough to feel like a second skin. Wear her as a daily verse of quiet courage. Adorn your own gemstone and flow with your own current.</span></p>", "price": 2600.0, "compare_at_price": null, "sku": "RGGE007", "stock": 5, "gemstone": "aquamarine", "cut": null, "carat": 0.5, "clarity": null, "metal": "925 Silver", "images": ["https://qsjzdfwvxshuazhgqoll.supabase.co/storage/v1/object/sign/admin-media/2026/cfcb3849-a053-451d-afab-f55085fb0766-aqua__1_.jpg?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV85ZDgyYzI2Zi0zY2Y2LTQ1MTQtOWJlYy1hZjQ1MTlmNmE1ZmUiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJhZG1pbi1tZWRpYS8yMDI2L2NmY2IzODQ5LWEwNTMtNDUxZC1hZmFiLWY1NTA4NWZiMDc2Ni1hcXVhX18xXy5qcGciLCJzY29wZSI6ImRvd25sb2FkIiwiaWF0IjoxNzg2MzU0MTg3LCJleHAiOjI0MTcwNzQxODd9.XeAZSn3VcWMQcug48aQtB3pBFLRXGB1DeyUfVjX9NkI", "https://qsjzdfwvxshuazhgqoll.supabase.co/storage/v1/object/sign/admin-media/2026/867f2675-0880-4991-b07e-c1a7eb063835-aquamarii__1_.jpg?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV85ZDgyYzI2Zi0zY2Y2LTQ1MTQtOWJlYy1hZjQ1MTlmNmE1ZmUiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJhZG1pbi1tZWRpYS8yMDI2Lzg2N2YyNjc1LTA4ODAtNDk5MS1iMDdlLWMxYTdlYjA2MzgzNS1hcXVhbWFyaWlfXzFfLmpwZyI